<?php
require_once __DIR__ . '/../../config/config.php';
require_roles(['ADMIN','HR']);$pdo=db();$id=(int)($_GET['id']??0);$employee=phase2_require_employee($pdo,$id);$profile=$pdo->prepare('SELECT * FROM employee_profiles WHERE employee_id=?');$profile->execute([$id]);$profile=$profile->fetch()?:[];$emergency=$pdo->prepare('SELECT * FROM emergency_contacts WHERE employee_id=? ORDER BY id DESC LIMIT 1');$emergency->execute([$id]);$emergency=$emergency->fetch()?:[];$history=$pdo->prepare('SELECT h.*,pd.name previous_department,pp.name previous_position,nd.name new_department,np.name new_position,u.username FROM employment_histories h LEFT JOIN departments pd ON pd.id=h.previous_department_id LEFT JOIN positions pp ON pp.id=h.previous_position_id LEFT JOIN departments nd ON nd.id=h.department_id LEFT JOIN positions np ON np.id=h.position_id LEFT JOIN users u ON u.id=h.performed_by WHERE h.employee_id=? ORDER BY h.effective_date DESC,h.id DESC');$history->execute([$id]);$history=$history->fetchAll();$documents=$pdo->prepare('SELECT d.*,t.name type_name FROM employee_documents d JOIN document_types t ON t.id=d.document_type_id WHERE d.employee_id=? ORDER BY d.created_at DESC');$documents->execute([$id]);$documents=$documents->fetchAll();$audits=$pdo->prepare('SELECT a.*,u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity_type="employees" AND a.entity_id=? ORDER BY a.created_at DESC LIMIT 10');$audits->execute([$id]);$audits=$audits->fetchAll();$pageTitle=$employee['first_name'].' '.$employee['last_name'];require __DIR__.'/../../includes/header.php';?><div class="flex flex-col md:flex-row md:justify-between gap-4 mb-7"><div><a href="index.php" class="text-sm font-bold text-teal-700">← Employees</a><h1 class="font-display text-3xl font-bold mt-2"><?=e($employee['first_name'].' '.$employee['last_name'])?></h1><p class="text-slate-500"><?=e($employee['employee_number'])?> · <?=e($employee['position_name']??'Unassigned')?></p></div><div class="flex gap-2"><a href="edit.php?id=<?=$id?>" class="rounded-lg border px-4 py-3 text-sm font-bold">Edit</a><a href="lifecycle.php?id=<?=$id?>" class="rounded-lg bg-teal-700 px-4 py-3 text-sm font-bold text-white">Lifecycle</a><a href="../employee-records/index.php?employee_id=<?=$id?>" class="rounded-lg bg-slate-900 px-4 py-3 text-sm font-bold text-white">Employee Records</a></div></div><div class="grid xl:grid-cols-3 gap-6"><section class="bg-white border border-slate-200 rounded-xl p-6"><h2 class="font-display text-xl font-bold">Personal information</h2><div class="grid grid-cols-2 gap-4 mt-5 text-sm"><?php foreach(['Employee ID'=>'employee_number','Date of birth'=>'date_of_birth','Gender'=>'gender','Civil status'=>'civil_status','Nationality'=>'nationality'] as $label=>$field):?><div><p class="text-xs text-slate-400"><?=e($label)?></p><p class="font-semibold mt-1"><?=e($employee[$field]??'—')?></p></div><?php endforeach;?></div></section><section class="bg-white border border-slate-200 rounded-xl p-6"><h2 class="font-display text-xl font-bold">Contact information</h2><div class="space-y-4 mt-5 text-sm"><?php foreach(['Email'=>'email','Phone'=>'phone','Address'=>'address','City'=>'city','Province'=>'province','Postal code'=>'postal_code'] as $label=>$field):?><div><p class="text-xs text-slate-400"><?=e($label)?></p><p class="font-semibold mt-1"><?=e($employee[$field]??'—')?></p></div><?php endforeach;?></div></section><section class="bg-white border border-slate-200 rounded-xl p-6"><h2 class="font-display text-xl font-bold">Employment information</h2><div class="space-y-4 mt-5 text-sm"><?php foreach(['Department'=>'department_name','Position'=>'position_name','Branch'=>'branch_name','Status'=>'employment_status','Type'=>'employment_type','Date hired'=>'date_hired','Probation end'=>'probation_end_date'] as $label=>$field):?><div class="flex justify-between gap-3"><span class="text-slate-400"><?=e($label)?></span><b><?=e($employee[$field]??'—')?></b></div><?php endforeach;?></div></section></div><div class="grid xl:grid-cols-2 gap-6 mt-6"><section class="bg-white border border-slate-200 rounded-xl p-6"><h2 class="font-display text-xl font-bold">Emergency contact</h2><?php if($emergency):?><div class="mt-5 text-sm space-y-3"><p><b><?=e($emergency['name'])?></b> · <?=e($emergency['relationship']??'')?></p><p><?=e($emergency['phone'])?></p><p class="text-slate-500"><?=e($emergency['address']??'—')?></p></div><?php else:?><p class="mt-5 text-sm text-slate-500">No emergency contact recorded.</p><?php endif;?></section><section class="bg-white border border-slate-200 rounded-xl p-6"><div class="flex justify-between"><h2 class="font-display text-xl font-bold">Documents</h2><a class="font-bold text-teal-700 text-sm" href="../employee-records/index.php?employee_id=<?=$id?>">Manage</a></div><?php if(!$documents):?><p class="mt-5 text-sm text-slate-500">No documents recorded.</p><?php else:?><div class="mt-4 space-y-3"><?php foreach($documents as $document):?><div class="flex justify-between border-b pb-3"><span><b><?=e($document['title'])?></b><small class="block text-slate-400"><?=e($document['type_name'])?></small></span><span class="text-xs font-bold text-teal-700"><?=e($document['status'])?></span></div><?php endforeach;?></div><?php endif;?></section></div><section class="bg-white border border-slate-200 rounded-xl p-6 mt-6"><h2 class="font-display text-xl font-bold">Employment history</h2><div class="overflow-x-auto mt-4"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Effective</th><th>Event</th><th>Department</th><th>Position</th><th>Status</th><th>Reason</th><th>By</th></tr></thead><tbody class="divide-y"><?php foreach($history as $item):?><tr><td class="py-3"><?=e($item['effective_date'])?></td><td><?=e($item['event_type'])?></td><td><?=e(($item['previous_department']??'—').' → '.($item['new_department']??'—'))?></td><td><?=e(($item['previous_position']??'—').' → '.($item['new_position']??'—'))?></td><td><?=e(($item['previous_status']??'—').' → '.($item['new_status']??'—'))?></td><td><?=e($item['reason']??'')?></td><td><?=e($item['username']??'System')?></td></tr><?php endforeach;?></tbody></table><?php if(!$history):?><p class="py-5 text-sm text-slate-500">No history recorded.</p><?php endif;?></div></section><?php require __DIR__.'/../../includes/footer.php';